import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
import pandas as pd
from scipy import stats

# ── helpers ──────────────────────────────────────────────────────────────────
corrective_types = {
    'cm','em','corrective','corrective maintenance','emergency',
    'emergency maintenance','emergency repair','breakdown',
    'breakdown maintenance','breakdown repair','reactive',
    'reactive maintenance','unplanned','unplanned maintenance',
    'unplanned breakdown','repair','fault','failure'
}
open_statuses = {
    'inprg','in progress','wappr','waiting on approval','appr','approved',
    'wmatl','waiting on material','wsched','waiting to be scheduled','open','hold'
}

df_a = df[df['row_kind'] != 'cancel'].copy()
for c in ['REPORTDATE','ACTSTART','ACTFINISH']:
    df_a[c] = pd.to_datetime(df_a[c], utc=True, errors='coerce')

df_a['wt_lo']  = df_a['WORKTYPE'].str.lower().str.strip()
df_a['st_lo']  = df_a['STATUS'].str.lower().str.strip()

df_corr = df_a[df_a['wt_lo'].isin(corrective_types)].copy()
# repair_hours: use existing column; guard if absent
if 'repair_hours' in df_corr.columns:
    df_corr = df_corr[df_corr['repair_hours'] >= 0]
    rh_col_exists = True
else:
    rh_col_exists = False

df_open = df_a[df_a['st_lo'].isin(open_statuses)]

# ── EDA ───────────────────────────────────────────────────────────────────────
try:
    eda = {}
    if rh_col_exists and df_corr['repair_hours'].notna().sum() >= 1:
        rh = df_corr['repair_hours'].dropna()
        eda['repair_hours'] = {
            'mean':   float(rh.mean()),
            'std':    float(rh.std()),
            'min':    float(rh.min()),
            'max':    float(rh.max()),
            'median': float(rh.median()),
            'count':  int(rh.count()),
        }
    result['eda_summary'] = eda
except Exception:
    pass

# ── SEGMENTATION ──────────────────────────────────────────────────────────────
try:
    segs = []

    # WO count by WORKTYPE
    wt_cnt = df_a.groupby('WORKTYPE')['WONUM'].nunique().sort_values(ascending=False).head(10)
    segs.append({
        'segment_column': 'WORKTYPE', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': float(v)} for k, v in wt_cnt.items()]
    })

    # WO count by STATUS
    st_cnt = df_a.groupby('STATUS')['WONUM'].nunique().sort_values(ascending=False).head(10)
    segs.append({
        'segment_column': 'STATUS', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': float(v)} for k, v in st_cnt.items()]
    })

    # WO count by FAILURECODE (non-null only)
    fc_cnt = (df_a[df_a['FAILURECODE'].notna()]
              .groupby('FAILURECODE')['WONUM'].nunique()
              .sort_values(ascending=False).head(10))
    segs.append({
        'segment_column': 'FAILURECODE', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': float(v)} for k, v in fc_cnt.items()]
    })

    # WO count by ASSETNUM (top 10)
    asset_cnt = df_a.groupby('ASSETNUM')['WONUM'].nunique().sort_values(ascending=False).head(10)
    segs.append({
        'segment_column': 'ASSETNUM', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': float(v)} for k, v in asset_cnt.items()]
    })

    # MTTR by FAILURECODE (corrective, repair_hours available)
    if rh_col_exists and len(df_corr) > 0 and df_corr['FAILURECODE'].notna().any():
        def _mttr(g):
            n = g['WONUM'].nunique()
            return g['repair_hours'].sum() / n if n > 0 else np.nan
        mttr_fc = (df_corr[df_corr['FAILURECODE'].notna()]
                   .groupby('FAILURECODE').apply(_mttr)
                   .dropna().sort_values(ascending=False).head(10))
        segs.append({
            'segment_column': 'FAILURECODE', 'metric_column': 'repair_hours',
            'aggregation': 'mean', 'label': 'mttr_by_failure_code',
            'results': [{'name': str(k), 'value': float(v)} for k, v in mttr_fc.items()]
        })

    # MTTR by ASSETNUM (corrective)
    if rh_col_exists and len(df_corr) > 0:
        mttr_asset = (df_corr.groupby('ASSETNUM').apply(_mttr)
                      .dropna().sort_values(ascending=False).head(10))
        segs.append({
            'segment_column': 'ASSETNUM', 'metric_column': 'repair_hours',
            'aggregation': 'mean', 'label': 'mttr_by_asset',
            'results': [{'name': str(k), 'value': float(v)} for k, v in mttr_asset.items()]
        })

    # WORKTYPE × STATUS breakdown
    wt_st = (df_a.groupby(['WORKTYPE','STATUS'])['WONUM'].nunique()
             .reset_index().sort_values('WONUM', ascending=False).head(10))
    segs.append({
        'segment_column': 'WORKTYPE|STATUS', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': None,
        'results': [{'name': f"{r['WORKTYPE']}|{r['STATUS']}", 'value': float(r['WONUM'])}
                    for _, r in wt_st.iterrows()]
    })

    result['segments'] = segs
except Exception:
    pass

# ── TRENDS ────────────────────────────────────────────────────────────────────
try:
    trends = []
    df_a['report_month'] = df_a['REPORTDATE'].dt.to_period('M')

    # Overall WO count MoM
    mo_wo = df_a.groupby('report_month')['WONUM'].nunique().sort_index()
    if len(mo_wo) >= 2:
        pct = float((mo_wo.iloc[-1] - mo_wo.iloc[-2]) / mo_wo.iloc[-2] * 100) if mo_wo.iloc[-2] else 0.0
        trends.append({'column': 'WONUM', 'period': 'MoM',
                       'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
                       'pct_change': round(pct, 2), 'segment': None})

    # MTTR MoM (corrective)
    if rh_col_exists and len(df_corr) > 0:
        df_corr['report_month'] = df_corr['REPORTDATE'].dt.to_period('M')
        mo_mttr = (df_corr.groupby('report_month')
                   .apply(lambda g: g['repair_hours'].sum() / g['WONUM'].nunique()
                          if g['WONUM'].nunique() > 0 else np.nan)
                   .dropna().sort_index())
        if len(mo_mttr) >= 2:
            pm = float((mo_mttr.iloc[-1] - mo_mttr.iloc[-2]) / mo_mttr.iloc[-2] * 100) if mo_mttr.iloc[-2] else 0.0
            trends.append({'column': 'repair_hours', 'period': 'MoM',
                           'direction': 'up' if pm > 1 else ('down' if pm < -1 else 'flat'),
                           'pct_change': round(pm, 2), 'segment': 'corrective_mttr'})

    # WO count MoM per WORKTYPE
    for wt in df_a['WORKTYPE'].dropna().unique():
        sub = (df_a[df_a['WORKTYPE'] == wt]
               .groupby('report_month')['WONUM'].nunique().sort_index())
        if len(sub) >= 2:
            pw = float((sub.iloc[-1] - sub.iloc[-2]) / sub.iloc[-2] * 100) if sub.iloc[-2] else 0.0
            trends.append({'column': 'WONUM', 'period': 'MoM',
                           'direction': 'up' if pw > 1 else ('down' if pw < -1 else 'flat'),
                           'pct_change': round(pw, 2), 'segment': str(wt)})

    result['trends'] = trends
except Exception:
    pass

# ── ANOMALIES ─────────────────────────────────────────────────────────────────
try:
    anomalies = []
    if rh_col_exists and len(df_corr) > 0:
        rh = df_corr['repair_hours'].dropna()
        if rh.nunique() >= 5 and len(rh) >= 5:
            skew = float(rh.skew())
            shift = max(0.0, -float(rh.min()))
            if abs(skew) > 2:
                rh_t = np.log1p(rh + shift)
            else:
                rh_t = rh.copy()
                shift = 0.0
            q1, q3 = float(rh_t.quantile(0.25)), float(rh_t.quantile(0.75))
            iqr = q3 - q1
            lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_t) - shift)
                hi_orig = float(np.expm1(hi_t) - shift)
            else:
                lo_orig, hi_orig = lo_t, hi_t

            mask = (rh < lo_orig) | (rh > hi_orig)
            flag_pct = mask.sum() / len(rh)
            exp_range = f'{lo_orig:.2f} to {hi_orig:.2f} hours'

            if flag_pct > 0.05:
                anomalies.append({
                    'column': 'repair_hours', 'row_index': None, 'value': None,
                    'expected_range': exp_range, 'severity': 'low',
                    'explanation': f'repair_hours is heavy-tailed; expected range {exp_range}'
                })
            else:
                flagged_idx = rh[mask].index
                for idx in flagged_idx[:25]:
                    val = float(df_corr.loc[idx, 'repair_hours'])
                    if abs(skew) > 2:
                        vt = float(np.log1p(val + shift))
                    else:
                        vt = val
                    hi5, hi4 = q3 + 5*iqr, q3 + 4*iqr
                    lo5, lo4 = q1 - 5*iqr, q1 - 4*iqr
                    sev = ('critical' if (vt > hi5 or vt < lo5) else
                           'high'     if (vt > hi4 or vt < lo4) else 'medium')
                    anomalies.append({
                        'column': 'repair_hours', 'row_index': int(idx), 'value': val,
                        'expected_range': exp_range, 'severity': sev,
                        'explanation': f'repair_hours value {val:.2f} lies outside expected range {exp_range}'
                    })
    result['anomalies'] = anomalies
except Exception:
    pass

result['assumptions'] = [
    'Cancelled work orders (row_kind=cancel) excluded from all metrics.',
    'MTTR uses repair_hours column (pre-computed); only corrective/CM/EM types with repair_hours >= 0.',
    'EDA eda_summary covers repair_hours only (the sole numeric column available).',
    'Trend MoM compares the last two available calendar months in REPORTDATE.',
    'Anomaly IQR boundary is Q1-3×IQR / Q3+3×IQR; log1p applied when |skew| > 2.',
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'ASSETNUM' in df.columns:
        _vc = df['ASSETNUM'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['ASSETNUM'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'WORKTYPE' in df.columns:
        _vc = df['WORKTYPE'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['WORKTYPE'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'STATUS' in df.columns:
        _vc = df['STATUS'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['STATUS'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'FAILURECODE' in df.columns:
        _vc = df['FAILURECODE'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['FAILURECODE'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'REPORTEDBY' in df.columns:
        _vc = df['REPORTEDBY'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['REPORTEDBY'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass
print(json.dumps(result, default=str))

